export function tangled(a: number): number {
  let x = a;
  if (a > 0) { x += 1; }
  if (a > 1) { x += 2; }
  if (a > 2) { x += 3; }
  if (a > 3) { x += 4; }
  if (a > 4) { x += 5; }
  if (a > 5) { x += 6; }
  if (a > 6) { x += 7; }
  if (a > 7) { x += 8; }
  if (a > 8) { x += 9; }
  if (a > 9) { x += 10; }
  if (a > 10) { x += 11; }
  if (a > 11) { x += 12; }
  if (a > 12) { x += 13; }
  if (a > 13) { x += 14; }
  if (a > 14) { x += 15; }
  if (a > 15) { x += 16; }
  return x;
}
